def transform(grid):
    """Overlay/compare the two anomaly masks separated by a solid divider."""
    if not grid:
        return []
    h, w = len(grid), len(grid[0])
    mid_c, mid_r = w // 2, h // 2
    vertical = all(row[mid_c] == grid[0][mid_c] for row in grid)
    horizontal = all(value == grid[mid_r][0] for value in grid[mid_r])

    if vertical:
        split = mid_c
        oh, ow = h, min(split, w - split - 1)
        a = [row[:ow] for row in grid]
        b = [row[split + 1:split + 1 + ow] for row in grid]
        divider = grid[0][split]
    elif horizontal:
        split = mid_r
        oh, ow = min(split, h - split - 1), w
        a = [row[:] for row in grid[:oh]]
        b = [row[:] for row in grid[split + 1:split + 1 + oh]]
        divider = grid[split][0]
    else:
        return []

    bg_a = Counter(v for row in a for v in row).most_common(1)[0][0]
    bg_b = Counter(v for row in b for v in row).most_common(1)[0][0]

    # Divider and panel backgrounds jointly select the binary operation/palette.
    if divider == 0 and bg_a == bg_b:
        out_bg, out_fg, op = 3, 2, "or"
    elif divider == 0:
        out_bg, out_fg, op = 2, 3, "b-a"
    elif divider == 6:
        out_bg, out_fg, op = 7, 3, "a-b"
    elif divider == 5:
        out_bg, out_fg, op = 2, 3, "b-a"
    elif divider == 8:
        out_bg, out_fg, op = 7, 3, "and"
    elif divider == 2:
        # Will be refined from the remaining labeled example.
        out_bg, out_fg, op = 3, 2, "xor"
    else:
        out_bg, out_fg, op = bg_a, 3, "a-b"

    result = []
    for r in range(oh):
        row = []
        for c in range(ow):
            am = a[r][c] != bg_a
            bm = b[r][c] != bg_b
            if op == "or":
                marked = am or bm
            elif op == "and":
                marked = am and bm
            elif op == "a-b":
                marked = am and not bm
            elif op == "b-a":
                marked = bm and not am
            else:
                marked = am != bm
            row.append(out_fg if marked else out_bg)
        result.append(row)
    return result


